import lazyload from '@/utils/lazyload';
import { IconProps } from '@arco-design/web-react/icon';
import React from 'react';
import { memo, useEffect, useState } from 'react';
import * as arcoIcon from '@arco-design/web-react/icon';

interface IconView extends IconProps {
    value: string;
}

/**
 * 定义Icon 图标
 */
export default memo(({ value, ...props }: IconView) => {
    const Element = arcoIcon[value];

    if(value && typeof value === 'object'){
        return React.cloneElement(value, props)
    }
    if(Element) return <Element data-icon={value} {...props} />
    return <span />;
})